    `).get(t,n);return i?{planId:i.plan_id,planVersion:i.plan_version,id:i.id,dayOfWeek:i.day_of_week,date:i.workout_date,focus:i.focus,type:i.type,durationMinutes:i.duration_minutes,intensity:i.intensity,targetMuscleGroups:F(i.target_muscle_groups_json,[]),exerciseIds:F(i.exercise_ids_json,[]),exercises:F(i.exercises_json,[]),rationale:i.rationale}:null}async saveOutcome(t,{userId:n=null,decisionId:i=null}={}){return this.db.prepare(`
