    `).all(...n?[t,n]:[t]).map(r=>({outcomeId:r.outcome_id,caseId:r.case_id,outcome:F(r.outcome_json,{}),recordedAt:r.recorded_at,userId:r.user_id,decisionId:r.decision_id}))}saveDecisionRecord(t){return this.db.prepare(`
